    final String string2 = o2.toString();
    // No guarantee that toString() returns a non-null value, despite what Spotbugs thinks.
    if (string1 == string2) {
        return 0;
    }
    if (string1 == null) {
        return 1;
    }
    if (string2 == null) {
        return -1;
    }
    return string1.compareTo(string2);
}

